 async function drawPicker(){dialog.dataset.exerciseView='picker';choices.close(false,true);const atlas=getAtlas(),rows=[...new Set(atlas.data.students.map(p=>p.id).concat(atlas.data.answers.map(a=>a.sid)))].map(sid=>atlas.materialAt(sid,'latest')).filter(Boolean),classes=[...new Set(rows.map(r=>r.classNo))].sort((a,b)=>a-b);if(!classes.includes(picker.classNo))picker.classNo=classes[0];const shown=rows.filter(r=>r.classNo===picker.classNo&&atlas.name(r.sid).includes(picker.search));renderInto(root,'<div class="inbox-top"><span class="overline">个性化辅导中心</span>'+action('×','close','icon-only','aria-label="关闭辅导中心"')+'</div><header class="report-heading"><h2 id="exercise-title">先找到学生，再确定训练。</h2><p>按最新考试或多次考试的共性失分，安排专项练习与复核。</p></header><section class="exercise-roster"><h3>选择班级</h3><div class="chips">'+classes.map(no=>action(no+'班','pick-class',no===picker.classNo?'chip selected':'chip','data-ai-value="'+no+'"')).join('')+'</div><label class="field"><span>查找本班学生</span><input data-ai-search value="'+esc(picker.search)+'" placeholder="输入学生姓名"></label><p class="report-help">'+picker.classNo+'班 · '+shown.length+'位学生</p><div class="exercise-student-grid">'+shown.map(r=>action(atlas.name(r.sid)+' · '+atlas.exam(r.exam).label,'pick-student','exercise-person','data-ai-sid="'+esc(r.sid)+'" data-ai-exam="'+esc(r.exam)+'"')).join('')+'</div>'+(!shown.length?'<p>当前班级没有匹配的学生，可调整检索或补充材料。</p>':'')+'</section>');enhance(root,{reveal:false});}

 const savedSettings=preference('exerciseConnection',{}),settings={url:exerciseServiceURL,token:savedSettings.url&&savedSettings.url!==exerciseServiceURL?'':savedSettings.token||'',expires:savedSettings.url&&savedSettings.url!==exerciseServiceURL?0:savedSettings.expires||0};
