 const persist=()=>{remember('exercisePending',records.some(r=>pendingJob(r)||pendingImages(r)));center.render();const snapshot=structuredClone(records);saving=saving.catch(()=>{}).then(()=>write([['exercises',snapshot]]));saving.catch(()=>notify('练习的本机保存未完成，请先下载已审题的练习'));return saving;};
 const wheels=installExerciseWheels(root,(field,value)=>{request[field]=value;delete fieldErrors[field];root.querySelector('#exercise-'+field+'-error')?.remove();root.querySelector('[data-exercise-wheel="'+field+'"]')?.removeAttribute('aria-invalid');updateSelectionSummary();});
 const rememberSettings=()=>remember('exerciseConnection',settings);
