 const draftKey=subject=>context.sid+'|'+context.exam+'|'+subject;
 function makeRequest(subject){const plan=context.plan?.training?.key===subject+'|'+context.exam?context.plan:null,analysed=analyzeExerciseBasis(getAtlas(),{...context,subject,plan,mode:'latest'}),evidence=analysed.evidence,focus=plan?.training?.goal||[...new Set(evidence.flatMap(e=>e.knowledge.split(/[,，;；]/)).filter(Boolean))].slice(0,3).join('、');return {subject,grade:'高三',curriculum:'',focus,count:Math.min(12,Math.max(3,Number(plan?.training?.count)||6)),minutes:Math.min(90,Math.max(5,Number(plan?.schedule?.duration)||15)),difficulty:'基础巩固',evidence,basis:analysed.basis,visuals:'vector',template:'targeted'};}
 function chooseSubject(subject){request={subject};current=eligible().at(-1)||null;request=current?structuredClone(current.request):structuredClone(drafts.get(draftKey(subject))||makeRequest(subject));if(current?.request.basis)basisSelections.set(draftKey(subject),{mode:current.request.basis.mode,exams:current.sourceExams||exerciseExams(getAtlas(),context.sid,subject).slice(-3).map(r=>r.exam)});}
 const readInputs=()=>{for(const input of root.querySelectorAll('[data-ai-field]'))request[input.dataset.aiField]=input.value;Object.assign(request,wheels.read());syncTargets();};
